import React, { useState, useEffect } from 'react';
import {
  View,
  StyleSheet,
  ScrollView,
  Alert,
} from 'react-native';
import {
  Card,
  Title,
  Paragraph,
  Button,
  Text,
  List,
  Divider,
  ActivityIndicator,
  Modal,
  TextInput,
} from 'react-native-paper';
import { LinearGradient } from 'expo-linear-gradient';
import { Ionicons } from '@expo/vector-icons';
import { paymentAPI } from '../../config/api';
import { theme, colors, spacing, typography } from '../../styles/theme';

export default function CardsScreen({ navigation }) {
  const [cards, setCards] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [showAddCardModal, setShowAddCardModal] = useState(false);
  const [isAddingCard, setIsAddingCard] = useState(false);
  const [newCard, setNewCard] = useState({
    cardNumber: '',
    expMonth: '',
    expYear: '',
    cvc: '',
    cardholderName: '',
  });

  useEffect(() => {
    loadCards();
  }, []);

  const loadCards = async () => {
    try {
      const response = await paymentAPI.getCards();
      setCards(response.data.cards);
    } catch (error) {
      console.error('Error loading cards:', error);
      Alert.alert('Error', 'Failed to load cards');
    } finally {
      setIsLoading(false);
    }
  };

  const handleAddCard = async () => {
    if (!validateCardForm()) return;

    setIsAddingCard(true);
    try {
      await paymentAPI.linkCard(newCard);
      setShowAddCardModal(false);
      setNewCard({
        cardNumber: '',
        expMonth: '',
        expYear: '',
        cvc: '',
        cardholderName: '',
      });
      await loadCards();
      Alert.alert('Success', 'Card added successfully!');
    } catch (error) {
      console.error('Add card error:', error);
      Alert.alert(
        'Error',
        error.response?.data?.error || 'Failed to add card'
      );
    } finally {
      setIsAddingCard(false);
    }
  };

  const validateCardForm = () => {
    const { cardNumber, expMonth, expYear, cvc, cardholderName } = newCard;

    if (!cardNumber || !expMonth || !expYear || !cvc || !cardholderName) {
      Alert.alert('Error', 'Please fill in all fields');
      return false;
    }

    if (cardNumber.length < 16) {
      Alert.alert('Error', 'Please enter a valid card number');
      return false;
    }

    if (cvc.length < 3) {
      Alert.alert('Error', 'Please enter a valid CVC');
      return false;
    }

    return true;
  };

  const handleSetDefault = async (cardId) => {
    try {
      await paymentAPI.setDefaultCard(cardId);
      await loadCards();
      Alert.alert('Success', 'Default card updated successfully!');
    } catch (error) {
      console.error('Set default card error:', error);
      Alert.alert('Error', 'Failed to update default card');
    }
  };

  const handleRemoveCard = (cardId, cardInfo) => {
    Alert.alert(
      'Remove Card',
      `Are you sure you want to remove the ${cardInfo.brand} card ending in ${cardInfo.last4}?`,
      [
        {
          text: 'Cancel',
          style: 'cancel',
        },
        {
          text: 'Remove',
          style: 'destructive',
          onPress: () => performRemoveCard(cardId),
        },
      ]
    );
  };

  const performRemoveCard = async (cardId) => {
    try {
      await paymentAPI.removeCard(cardId);
      await loadCards();
      Alert.alert('Success', 'Card removed successfully!');
    } catch (error) {
      console.error('Remove card error:', error);
      Alert.alert('Error', 'Failed to remove card');
    }
  };

  const getCardIcon = (brand) => {
    switch (brand.toLowerCase()) {
      case 'visa':
        return 'credit-card';
      case 'mastercard':
        return 'credit-card';
      default:
        return 'credit-card-outline';
    }
  };

  const getBankColor = (bank) => {
    switch (bank) {
      case 'FNB':
        return '#1E3A8A';
      case 'Standard Bank':
        return '#059669';
      case 'Bank Windhoek':
        return '#DC2626';
      case 'Nedbank':
        return '#7C3AED';
      default:
        return colors.primary;
    }
  };

  if (isLoading) {
    return (
      <View style={styles.loadingContainer}>
        <ActivityIndicator size="large" color={colors.primary} />
        <Text style={styles.loadingText}>Loading cards...</Text>
      </View>
    );
  }

  return (
    <View style={styles.container}>
      {/* Header */}
      <LinearGradient
        colors={[colors.primary, colors.primaryDark]}
        style={styles.header}
      >
        <View style={styles.headerContent}>
          <Ionicons name="card" size={32} color={colors.white} />
          <Title style={styles.headerTitle}>My Cards</Title>
          <Paragraph style={styles.headerSubtitle}>
            Manage your payment cards
          </Paragraph>
        </View>
      </LinearGradient>

      <ScrollView style={styles.content}>
        {/* Add Card Button */}
        <Button
          mode="contained"
          onPress={() => setShowAddCardModal(true)}
          style={styles.addCardButton}
          icon="plus"
          theme={{
            colors: {
              primary: colors.primary,
            },
          }}
        >
          Add New Card
        </Button>

        {/* Cards List */}
        {cards.length > 0 ? (
          <View style={styles.cardsList}>
            {cards.map((card, index) => (
              <Card key={card.id} style={styles.cardItem}>
                <Card.Content>
                  <View style={styles.cardHeader}>
                    <View style={styles.cardInfo}>
                      <View style={styles.cardIcon}>
                        <Ionicons 
                          name={getCardIcon(card.brand)} 
                          size={24} 
                          color={getBankColor(card.bank)} 
                        />
                      </View>
                      <View style={styles.cardDetails}>
                        <Text style={styles.cardBrand}>{card.brand}</Text>
                        <Text style={styles.cardNumber}>**** **** **** {card.last4}</Text>
                        <Text style={styles.cardBank}>{card.bank}</Text>
                      </View>
                    </View>
                    {card.isDefault && (
                      <View style={styles.defaultBadge}>
                        <Text style={styles.defaultText}>DEFAULT</Text>
                      </View>
                    )}
                  </View>

                  <View style={styles.cardActions}>
                    {!card.isDefault && (
                      <Button
                        mode="outlined"
                        onPress={() => handleSetDefault(card.id)}
                        style={styles.actionButton}
                        compact
                        theme={{
                          colors: {
                            primary: colors.primary,
                          },
                        }}
                      >
                        Set Default
                      </Button>
                    )}
                    <Button
                      mode="outlined"
                      onPress={() => handleRemoveCard(card.id, card)}
                      style={[styles.actionButton, styles.removeButton]}
                      compact
                      textColor={colors.error}
                      theme={{
                        colors: {
                          primary: colors.error,
                        },
                      }}
                    >
                      Remove
                    </Button>
                  </View>
                </Card.Content>
              </Card>
            ))}
          </View>
        ) : (
          <Card style={styles.emptyCard}>
            <Card.Content style={styles.emptyContent}>
              <Ionicons name="card-outline" size={64} color={colors.gray} />
              <Title style={styles.emptyTitle}>No Cards Added</Title>
              <Paragraph style={styles.emptySubtitle}>
                Add a payment card to start making transactions
              </Paragraph>
            </Card.Content>
          </Card>
        )}

        {/* Test Cards Info */}
        <Card style={styles.testCard}>
          <Card.Content>
            <Title style={styles.testTitle}>Test Cards</Title>
            <Paragraph style={styles.testText}>
              For testing purposes, you can use these test card numbers:
            </Paragraph>
            <View style={styles.testCardsList}>
              <Text style={styles.testCardItem}>• FNB: 4242424242424242</Text>
              <Text style={styles.testCardItem}>• Standard Bank: 4000056655665556</Text>
              <Text style={styles.testCardItem}>• Bank Windhoek: 5555555555554444</Text>
              <Text style={styles.testCardItem}>• Nedbank: 2223003122003222</Text>
            </View>
            <Paragraph style={styles.testNote}>
              Use any future expiry date and any 3-digit CVC.
            </Paragraph>
          </Card.Content>
        </Card>
      </ScrollView>

      {/* Add Card Modal */}
      <Modal
        visible={showAddCardModal}
        onDismiss={() => setShowAddCardModal(false)}
        contentContainerStyle={styles.modalContainer}
      >
        <Card style={styles.modalCard}>
          <Card.Content>
            <Title style={styles.modalTitle}>Add New Card</Title>
            
            <TextInput
              label="Card Number"
              value={newCard.cardNumber}
              onChangeText={(value) => setNewCard({ ...newCard, cardNumber: value })}
              mode="outlined"
              keyboardType="numeric"
              placeholder="1234 5678 9012 3456"
              style={styles.modalInput}
              theme={{
                colors: {
                  primary: colors.primary,
                },
              }}
            />

            <View style={styles.expiryRow}>
              <TextInput
                label="Month"
                value={newCard.expMonth}
                onChangeText={(value) => setNewCard({ ...newCard, expMonth: value })}
                mode="outlined"
                keyboardType="numeric"
                placeholder="MM"
                style={[styles.modalInput, styles.halfInput]}
                theme={{
                  colors: {
                    primary: colors.primary,
                  },
                }}
              />
              <TextInput
                label="Year"
                value={newCard.expYear}
                onChangeText={(value) => setNewCard({ ...newCard, expYear: value })}
                mode="outlined"
                keyboardType="numeric"
                placeholder="YYYY"
                style={[styles.modalInput, styles.halfInput]}
                theme={{
                  colors: {
                    primary: colors.primary,
                  },
                }}
              />
            </View>

            <TextInput
              label="CVC"
              value={newCard.cvc}
              onChangeText={(value) => setNewCard({ ...newCard, cvc: value })}
              mode="outlined"
              keyboardType="numeric"
              placeholder="123"
              style={styles.modalInput}
              theme={{
                colors: {
                  primary: colors.primary,
                },
              }}
            />

            <TextInput
              label="Cardholder Name"
              value={newCard.cardholderName}
              onChangeText={(value) => setNewCard({ ...newCard, cardholderName: value })}
              mode="outlined"
              placeholder="John Doe"
              style={styles.modalInput}
              theme={{
                colors: {
                  primary: colors.primary,
                },
              }}
            />

            <View style={styles.modalActions}>
              <Button
                mode="outlined"
                onPress={() => setShowAddCardModal(false)}
                style={styles.modalButton}
                theme={{
                  colors: {
                    primary: colors.primary,
                  },
                }}
              >
                Cancel
              </Button>
              <Button
                mode="contained"
                onPress={handleAddCard}
                loading={isAddingCard}
                disabled={isAddingCard}
                style={styles.modalButton}
                theme={{
                  colors: {
                    primary: colors.primary,
                  },
                }}
              >
                Add Card
              </Button>
            </View>
          </Card.Content>
        </Card>
      </Modal>
    </View>
  );
}

